const tabla = document.getElementById("datos");

async function cargarProductos() {
    tabla.innerHTML = "<tr><td colspan='2'>Cargando productos...</td></tr>";

    try {
        const respuesta = await fetch("/api/productos");

        if (!respuesta.ok) {
            throw new Error(`Error HTTP ${respuesta.status}`);
        }

        const productos = await respuesta.json();

        tabla.innerHTML = "";

        for (const producto of productos) {
            const fila = document.createElement("tr");

            const nombre = document.createElement("td");
            nombre.textContent = producto.nombre;

            const existencias = document.createElement("td");
            existencias.textContent = producto.existencias;

            fila.append(nombre, existencias);
            tabla.appendChild(fila);
        }
    } catch (error) {
        console.error("Error al cargar productos:", error);
        tabla.innerHTML =
            "<tr><td colspan='2'>No se pudieron cargar los productos.</td></tr>";
    }
}

cargarProductos();